/* ═══════════════════════════════════════════════════════
   RURAL ELITE — Main JavaScript
   ═══════════════════════════════════════════════════════ */

(function () {
  'use strict';

  /* ── Countdown Timer ── */
  function initCountdown() {
    const STORAGE_KEY = 'ruralelite_cd_end';
    const HOURS = 23, MINS = 59, SECS = 59;

    let endTime = localStorage.getItem(STORAGE_KEY);
    if (!endTime) {
      endTime = Date.now() + (HOURS * 3600 + MINS * 60 + SECS) * 1000;
      localStorage.setItem(STORAGE_KEY, endTime);
    }
    endTime = parseInt(endTime, 10);

    function updateCD() {
      const diff = Math.max(0, endTime - Date.now());
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      const pad = (n) => String(n).padStart(2, '0');

      document.querySelectorAll('.cd-hours').forEach(el => el.textContent = pad(h));
      document.querySelectorAll('.cd-minutes').forEach(el => el.textContent = pad(m));
      document.querySelectorAll('.cd-seconds').forEach(el => el.textContent = pad(s));

      if (diff <= 0) {
        localStorage.removeItem(STORAGE_KEY);
        // Reset timer
        const newEnd = Date.now() + (23 * 3600 + 59 * 60 + 59) * 1000;
        localStorage.setItem(STORAGE_KEY, newEnd);
      }
    }

    updateCD();
    setInterval(updateCD, 1000);
  }

  /* ── Scroll Reveal (IntersectionObserver) ── */
  function initReveal() {
    const reveals = document.querySelectorAll('.reveal');
    if (!reveals.length) return;

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      });
    }, {
      threshold: 0.1,
      rootMargin: '0px 0px -40px 0px'
    });

    reveals.forEach(el => observer.observe(el));
  }

  /* ── FAQ Accordion ── */
  function initFAQ() {
    const items = document.querySelectorAll('.faq-item');
    items.forEach(item => {
      const btn = item.querySelector('.faq-q');
      if (!btn) return;

      btn.addEventListener('click', () => {
        const wasOpen = item.classList.contains('is-open');

        // Close all
        items.forEach(i => i.classList.remove('is-open'));

        // Toggle current
        if (!wasOpen) {
          item.classList.add('is-open');
        }
      });
    });
  }

  /* ── Testimonial Carousel ── */
  function initTestiCarousel() {
    const viewport = document.getElementById('testi-viewport');
    const dots = document.querySelectorAll('.testi-dot');
    if (!viewport || !dots.length) return;

    let currentIdx = 0;
    let autoTimer;

    function goTo(idx) {
      currentIdx = idx;
      const slideWidth = viewport.offsetWidth;
      viewport.scrollTo({ left: slideWidth * idx, behavior: 'smooth' });
      dots.forEach((d, i) => d.classList.toggle('is-active', i === idx));
    }

    // Dot clicks
    dots.forEach(dot => {
      dot.addEventListener('click', () => {
        const idx = parseInt(dot.dataset.index, 10);
        goTo(idx);
        resetAuto();
      });
    });

    // Auto-advance
    function startAuto() {
      autoTimer = setInterval(() => {
        const next = (currentIdx + 1) % dots.length;
        goTo(next);
      }, 4500);
    }

    function resetAuto() {
      clearInterval(autoTimer);
      startAuto();
    }

    // Touch/scroll sync
    let scrollTimeout;
    viewport.addEventListener('scroll', () => {
      clearTimeout(scrollTimeout);
      scrollTimeout = setTimeout(() => {
        const slideWidth = viewport.offsetWidth;
        const newIdx = Math.round(viewport.scrollLeft / slideWidth);
        if (newIdx !== currentIdx && newIdx >= 0 && newIdx < dots.length) {
          currentIdx = newIdx;
          dots.forEach((d, i) => d.classList.toggle('is-active', i === currentIdx));
        }
      }, 80);
    }, { passive: true });

    startAuto();
  }

  /* ── Protected Images — load data-bg ── */
  function initProtectedImages() {
    document.querySelectorAll('.protected-image[data-bg]').forEach(el => {
      el.style.backgroundImage = `url('${el.dataset.bg}')`;
    });
  }

  /* ── Anti-Clone Protection ── */
  function initAntiClone() {
    document.addEventListener('contextmenu', e => {
      if (e.target.tagName === 'IMG' || 
          e.target.classList.contains('protected-image-overlay') || 
          e.target.closest('.gal-img-wrap') || 
          e.target.closest('.bonus-capa-wrap') || 
          e.target.closest('.testi-shot')) {
        e.preventDefault();
      }
    });
    document.addEventListener('dragstart', e => {
      if (e.target.tagName === 'IMG' || e.target.classList.contains('protected-image-overlay')) {
        e.preventDefault();
      }
    });
  }

  /* ── Downsell Modal Logic ── */
  function initModal() {
    const modal = document.getElementById('downsell-modal');
    const overlay = document.getElementById('modal-overlay');
    const closeBtn = document.getElementById('modal-close');
    const btnBasic = document.getElementById('btn-basic');
    const modalBtnBasic = document.getElementById('modal-btn-basic');
    const btnPremium = document.getElementById('btn-premium');
    const modalBtnPremium = document.getElementById('modal-btn-premium');

    if (!modal) return;

    // Links — change these to your actual checkout URLs
    const BASIC_LINK = 'https://pay.cakto.com.br/38kjte4_1010536';
    const PREMIUM_LINK = 'https://pay.cakto.com.br/wnvxbby_1003446';

    function openModal() {
      modal.classList.add('is-visible');
      document.body.style.overflow = 'hidden';
      startModalCountdown();
    }

    function closeModal() {
      modal.classList.remove('is-visible');
      document.body.style.overflow = '';
    }

    // Basic button → show downsell modal
    if (btnBasic) {
      btnBasic.addEventListener('click', (e) => {
        e.preventDefault();
        openModal();
        // Track event if fbq exists
        if (typeof fbq === 'function') fbq('track', 'InitiateCheckout', { content_name: 'Basic Plan' });
      });
    }

    // Premium button → go to checkout
    if (btnPremium) {
      btnPremium.addEventListener('click', () => {
        if (typeof fbq === 'function') fbq('track', 'InitiateCheckout', { content_name: 'Premium Plan' });
        window.location.href = PREMIUM_LINK;
      });
    }

    // Modal → upgrade to premium
    if (modalBtnPremium) {
      modalBtnPremium.addEventListener('click', () => {
        if (typeof fbq === 'function') fbq('track', 'InitiateCheckout', { content_name: 'Premium Upsell' });
      });
    }

    // Modal → go basic
    if (modalBtnBasic) {
      modalBtnBasic.addEventListener('click', () => {
        closeModal();
        window.location.href = BASIC_LINK;
      });
    }

    // Close modal
    if (overlay) overlay.addEventListener('click', closeModal);
    if (closeBtn) closeBtn.addEventListener('click', closeModal);
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeModal();
    });

    // Modal countdown (15 min)
    let modalTimerInterval;
    function startModalCountdown() {
      const timerEl = document.getElementById('modal-countdown-timer');
      if (!timerEl) return;

      let totalSec = 15 * 60;
      clearInterval(modalTimerInterval);

      modalTimerInterval = setInterval(() => {
        totalSec--;
        if (totalSec <= 0) {
          clearInterval(modalTimerInterval);
          totalSec = 0;
        }
        const m = Math.floor(totalSec / 60);
        const s = totalSec % 60;
        timerEl.textContent = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
      }, 1000);
    }
  }

  /* ── Smooth Scroll for Anchor Links ── */
  function initSmoothScroll() {
    document.querySelectorAll('a[href^="#"]').forEach(link => {
      link.addEventListener('click', (e) => {
        const target = document.querySelector(link.getAttribute('href'));
        if (target) {
          e.preventDefault();
          const offset = 50;
          const top = target.getBoundingClientRect().top + window.pageYOffset - offset;
          window.scrollTo({ top, behavior: 'smooth' });
        }
      });
    });
  }

  /* ── Footer Year ── */
  function initYear() {
    const el = document.getElementById('footer-year');
    if (el) el.textContent = new Date().getFullYear();
  }

  /* ── Parallax effect on hero glow ── */
  function initParallax() {
    const glow = document.querySelector('.hero-glow');
    if (!glow || window.innerWidth < 768) return;

    window.addEventListener('mousemove', (e) => {
      const x = (e.clientX / window.innerWidth - 0.5) * 20;
      const y = (e.clientY / window.innerHeight - 0.5) * 20;
      glow.style.transform = `translateX(calc(-50% + ${x}px)) translateY(${y}px)`;
    }, { passive: true });
  }

  /* ── Navbar countdown bar hide on scroll down, show on scroll up ── */
  function initCountdownBarScroll() {
    const bar = document.querySelector('.countdown-bar');
    if (!bar) return;

    let lastScroll = 0;
    let ticking = false;

    window.addEventListener('scroll', () => {
      if (!ticking) {
        window.requestAnimationFrame(() => {
          const st = window.pageYOffset;
          if (st > lastScroll && st > 100) {
            bar.style.transform = 'translateY(-100%)';
          } else {
            bar.style.transform = 'translateY(0)';
          }
          bar.style.transition = 'transform 0.35s ease';
          lastScroll = st;
          ticking = false;
        });
        ticking = true;
      }
    }, { passive: true });
  }

  /* ── Touch swipe support for gallery on mobile ── */
  function initGalleryPause() {
    const track = document.querySelector('.gal-track');
    if (!track) return;

    track.addEventListener('mouseenter', () => {
      track.style.animationPlayState = 'paused';
    });
    track.addEventListener('mouseleave', () => {
      track.style.animationPlayState = 'running';
    });

    // Also pause on touch
    track.addEventListener('touchstart', () => {
      track.style.animationPlayState = 'paused';
    }, { passive: true });
    track.addEventListener('touchend', () => {
      setTimeout(() => {
        track.style.animationPlayState = 'running';
      }, 2000);
    }, { passive: true });
  }

  /* ── Init All ── */
  document.addEventListener('DOMContentLoaded', () => {
    initCountdown();
    initReveal();
    initFAQ();
    initTestiCarousel();
    initProtectedImages();
    initAntiClone();
    initModal();
    initSmoothScroll();
    initYear();
    initParallax();
    initCountdownBarScroll();
    initGalleryPause();
  });

})();
